// === SCORING DÉTERMINISTE — règles simples & explicables ===
// Lit review_queue (prospects) + project_queue (projets), calcule un score 0-10,
// renvoie items prêts pour LLM, gardés top N (limite coût).

const now = Date.now();
const run_id = 'pri_' + now;
const MAX_ITEMS = 30; // top 30 items envoyés au LLM

const prospects = $('Lire review_queue').all().map(i => i.json);
const projects  = $('Lire project_queue').all().map(i => i.json);

// --- Helpers ---
function num(v, def = 0) { const n = Number(v); return Number.isFinite(n) ? n : def; }
function daysSince(iso) {
  if (!iso) return 999;
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return 999;
  return Math.max(0, Math.floor((now - t) / 86400000));
}
function recencyScore(d) {
  // 0d=10, 7d=8, 14d=6, 30d=4, 60d=2, 90d+=1
  if (d <= 0) return 10;
  if (d <= 7) return 8;
  if (d <= 14) return 6;
  if (d <= 30) return 4;
  if (d <= 60) return 2;
  return 1;
}
function nicheFitScore(niche) {
  const n = String(niche || '').toLowerCase();
  // niches préférées Symbalyx : score plus élevé
  if (['plombier', 'electricien', 'artisan', 'coiffeur', 'salon'].includes(n)) return 9;
  if (['coach', 'consultant', 'photographe', 'restaurant'].includes(n)) return 7;
  if (n) return 5;
  return 3;
}
function replyBonus(cat) {
  const c = String(cat || '').toLowerCase();
  if (c === 'interested')   return 10;
  if (c === 'needs_quote')  return 9;
  if (c === 'ask_later')    return 5;
  if (c === 'unclear')      return 3;
  if (c === 'not_interested') return 0;
  return 0;
}
function urgencyFromDeadline(iso) {
  if (!iso) return 4;
  const d = (Date.parse(iso) - now) / 86400000;
  if (d <= 7) return 10;
  if (d <= 14) return 8;
  if (d <= 30) return 6;
  if (d <= 60) return 4;
  return 2;
}
function valueFromComplexity(c) {
  const x = String(c || '').toLowerCase();
  if (x === 'complex') return 8;
  if (x === 'medium')  return 6;
  if (x === 'simple')  return 4;
  return 5;
}

// --- Score prospects ---
const PPS_W = { opportunity: 0.35, easiness: 0.20, recency: 0.20, fit: 0.15, reply: 0.10 };
const scoredProspects = prospects
  .filter(p => {
    const optOut = p.opt_out === true || String(p.opt_out || '').toLowerCase() === 'true';
    return !optOut && String(p.status || '').toLowerCase() !== 'rejected';
  })
  .map(p => {
    const opp  = num(p.opportunity_score, 5);
    const diff = num(p.project_difficulty_score, 5);
    const easiness = 11 - diff;
    const last = p.reply_received_at || p.updated_at || p.created_at;
    const rec  = recencyScore(daysSince(last));
    const fit  = nicheFitScore(p.niche);
    const rep  = replyBonus(p.reply_category);

    const score = +(
      PPS_W.opportunity * opp +
      PPS_W.easiness    * easiness +
      PPS_W.recency     * rec +
      PPS_W.fit         * fit +
      PPS_W.reply       * rep
    ).toFixed(2);

    return {
      item_type: 'prospect',
      item_id: p.id,
      title: `${p.company_name || 'Prospect'} — ${p.city || ''} (${p.niche || '?'})`.trim(),
      score_raw: score,
      score_breakdown: {
        opportunity_score: opp,
        difficulty_score: diff,
        easiness, recency: rec, niche_fit: fit, reply_bonus: rep,
        days_since_last: daysSince(last)
      },
      data: {
        company_name: p.company_name,
        contact_name: p.contact_name,
        email: p.email,
        city: p.city,
        niche: p.niche,
        website_status: p.website_status,
        opportunity_reason: p.opportunity_reason,
        suggested_angle: p.suggested_angle,
        project_difficulty_label: p.project_difficulty_label,
        reply_category: p.reply_category,
        reply_text_excerpt: String(p.reply_text || '').slice(0, 200),
        status: p.status,
        opt_out: p.opt_out
      }
    };
  });

// --- Score projets ---
const PrPS_W = { urgency: 0.30, value: 0.25, easiness: 0.20, responsiveness: 0.15, fit: 0.10 };
const scoredProjects = projects
  .filter(p => ['new', 'in_progress'].includes(String(p.status || '').toLowerCase()))
  .map(p => {
    const urg = urgencyFromDeadline(p.deadline);
    const val = valueFromComplexity(p.estimated_project_complexity);
    const cmpx = (function () {
      const x = String(p.estimated_project_complexity || '').toLowerCase();
      if (x === 'simple') return 3;
      if (x === 'medium') return 5;
      if (x === 'complex') return 8;
      return 5;
    })();
    const easiness = 11 - cmpx;
    const resp = recencyScore(daysSince(p.updated_at));
    const fit  = nicheFitScore(p.niche);

    const score = +(
      PrPS_W.urgency       * urg +
      PrPS_W.value         * val +
      PrPS_W.easiness      * easiness +
      PrPS_W.responsiveness* resp +
      PrPS_W.fit           * fit
    ).toFixed(2);

    return {
      item_type: 'project',
      item_id: p.id,
      title: `${p.client_name || 'Projet'} — ${p.niche || ''} (${p.estimated_project_complexity || '?'})`.trim(),
      score_raw: score,
      score_breakdown: {
        urgency: urg, value: val, complexity: cmpx, easiness,
        responsiveness: resp, niche_fit: fit,
        days_since_update: daysSince(p.updated_at)
      },
      data: {
        client_name: p.client_name,
        niche: p.niche,
        city: p.city,
        complexity: p.estimated_project_complexity,
        scope_excerpt: String(p.estimated_project_scope || '').slice(0, 200),
        next_questions: p.next_questions_to_ask,
        status: p.status,
        assigned_to: p.assigned_to,
        deadline: p.deadline
      }
    };
  });

// --- Combine + tri + top N ---
const all = [...scoredProspects, ...scoredProjects]
  .sort((a, b) => b.score_raw - a.score_raw)
  .slice(0, MAX_ITEMS);

// On retourne 1 seul item avec un payload prêt LLM (batch unique)
return [{
  json: {
    run_id,
    items_count: all.length,
    items: all
  }
}];

