// Parse LLM + merge avec score déterministe + explode 1 ligne par recommandation
const llm = $json;
let parsed = { recommendations: [] };
try {
  const c = llm && llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
  if (c) parsed = JSON.parse(c);
} catch (e) {
  parsed = { recommendations: [], _llm_error: String(e && e.message || e) };
}

const ctx = $('Score déterministe (top N)').first().json;
const run_id = ctx.run_id;
const byId = new Map((ctx.items || []).map(i => [i.item_id, i]));
const now = new Date().toISOString();

const rows = (parsed.recommendations || []).map((r, idx) => {
  const det = byId.get(r.item_id) || {};
  return {
    json: {
      id: 'bcl_' + Date.now() + '_' + String(idx).padStart(3, '0'),
      ts: now,
      run_id,
      source_workflow: 'WF7',
      item_type: r.item_type,
      item_id: r.item_id,
      title: r.title || det.title || '',
      recommendation: r.recommendation || '',
      recommended_action: r.recommended_action || '',
      priority_score: det.score_raw != null ? det.score_raw : '',
      priority_level: r.priority_level || '',
      expected_impact: r.expected_impact || '',
      effort_level: r.effort_level || '',
      assigned_to: r.assigned_to || '',
      requires_human_validation: 'true',
      decision_status: 'pending',
      decided_by: '',
      decided_at: '',
      notes: r.reason || ''
    }
  };
});

if (rows.length === 0) {
  return [{
    json: {
      id: 'bcl_' + Date.now() + '_empty',
      ts: now,
      run_id,
      source_workflow: 'WF7',
      item_type: 'ops',
      item_id: '',
      title: 'WF7 — aucune reco',
      recommendation: parsed._llm_error ? ('LLM error: ' + parsed._llm_error) : 'Aucun item à prioriser cette exécution',
      recommended_action: 'review',
      priority_score: '',
      priority_level: 'low',
      expected_impact: 'low',
      effort_level: 'low',
      assigned_to: 'Arsène+Kentin',
      requires_human_validation: 'true',
      decision_status: 'pending',
      decided_by: '',
      decided_at: '',
      notes: ''
    }
  }];
}
return rows;
